import{_ as d,a0 as l,w as a,s as r,ao as p,I as n,x as t,a1 as s,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"介紹 Linux 中的管道和命名管道 | LCTT x X-CMD","titleTemplate":false,"description":"介紹 Linux 中的管道和命名管道 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"介紹 Linux 中的管道和命名管道 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"介紹 Linux 中的管道和命名管道 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180823 An introduction to pipes and named pipes in Linux","title":"介紹 Linux 中的管道和命名管道","tag":"201809","desc":""},"relativePath":"201809/20180823 An introduction to pipes and named pipes in Linux.md","filePath":"[post].md"}'),u={name:"201809/20180823 An introduction to pipes and named pipes in Linux.md"};function c(m,e,g,f,k,x){const i=l("Link");return a(),r("div",null,[e[18]||(e[18]=p('<h1 id="介紹-linux-中的管道和命名管道" tabindex="-1">介紹 Linux 中的管道和命名管道 <a class="header-anchor" href="#介紹-linux-中的管道和命名管道" aria-label="Permalink to “介紹 Linux 中的管道和命名管道”">​</a></h1><blockquote><p>要在命令間移動數據？使用管道可使此過程便捷。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/LAW-Internet_construction_9401467_520x292_0512_dc.png?itok=RPkPPtDe" alt=""></p><p>在 Linux 中，<code>pipe</code> 能讓你將一個命令的輸出發送給另一個命令。管道，如它的名稱那樣，能重定向一個進程的標準輸出、輸入和錯誤到另一個進程，以便於進一步處理。</p><p>“管道”（或稱“未命名管道”）命令的語法是在兩個命令之間加上 <code>|</code> 字符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Command-1 | Command-2 | ...| Command-N</span></span></code></pre></div><p>這裏，該管道不能通過另一個會話訪問；它被臨時創建用於接收 <code>Command-1</code> 的執行並重定向標準輸出。它在成功執行之後刪除。</p><p><img src="https://opensource.com/sites/default/files/uploads/pipe.png" alt=""></p><p>在上面的示例中，<code>contents.txt</code> 包含特定目錄中所有文件的列表 —— 具體來説，就是 <code>ls -al</code> 命令的輸出。我們首先通過管道（如圖所示）使用 “file” 關鍵字從 <code>contents.txt</code> 中 <code>grep</code> 文件名，因此 <code>cat</code> 命令的輸出作為 <code>grep</code> 命令的輸入提供。接下來，我們添加管道來執行 <code>awk</code> 命令，該命令顯示 <code>grep</code> 命令的過濾輸出中的第 9 列。我們還可以使用 <code>wc -l</code> 命令計算 <code>contents.txt</code> 中的行數。</p>',9)),n("p",null,[e[1]||(e[1]=t("只要系統啓動並運行或直到它被刪除，命名管道就可以持續使用。它是一個遵循 ",-1)),s(i,{href:"https://en.wikipedia.org/wiki/FIFO_(computing_and_electronics)"},{default:o(()=>[...e[0]||(e[0]=[t("FIFO",-1)])]),_:1}),e[2]||(e[2]=t("（先進先出）機制的特殊文件。它可以像普通文件一樣使用。也就是，你可以寫入，從中讀取，然後打開或關閉它。要創建命名管道，命令為：",-1))]),e[19]||(e[19]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkfifo &lt;pipe-name&gt;</span></span></code></pre></div><p>這將創建一個命名管道文件，它甚至可以在多個 shell 會話中使用。</p><p>創建 FIFO 命名管道的另一種方法是使用此命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mknod p &lt;pipe-name&gt;</span></span></code></pre></div><p>要重定向任何命令的標準輸出到其它命令，請使用 <code>&gt;</code> 符號。要重定向任何命令的標準輸入，請使用 <code>&lt;</code> 符號。</p><p><img src="https://opensource.com/sites/default/files/uploads/redirection.png" alt=""></p><p>如上所示，<code>ls -al</code> 命令的輸出被重定向到 <code>contents.txt</code> 並插入到文件中。類似地，<code>tail</code> 命令的輸入通過 <code>&lt;</code> 符號從 <code>contents.txt</code> 讀取。</p><p><img src="https://opensource.com/sites/default/files/uploads/create-named-pipe.png" alt=""></p><p><img src="https://opensource.com/sites/default/files/uploads/verify-output.png" alt=""></p><p>這裏，我們創建了一個命名管道 <code>my-named-pipe</code>，並將 <code>ls -al</code> 命令的輸出重定向到命名管道。我們可以打開一個新的 shell 會話並 <code>cat</code> 命名管道的內容，如前所述，它顯示了 <code>ls -al</code> 命令的輸出。請注意，命名管道的大小為零，並有一個標誌 “p”。</p><p>因此，下次你在 Linux 終端上使用命令並在命令之間移動數據時，希望管道使這個過程快速簡便。</p><hr>',12)),n("p",null,[e[4]||(e[4]=t("via: ",-1)),s(i,{href:"https://opensource.com/article/18/8/introduction-pipes-linux"},{default:o(()=>[...e[3]||(e[3]=[t("https://opensource.com/article/18/8/introduction-pipes-linux",-1)])]),_:1})]),n("p",null,[e[9]||(e[9]=t("作者：",-1)),s(i,{href:"https://opensource.com/users/architmodi"},{default:o(()=>[...e[5]||(e[5]=[t("Archit Modi",-1)])]),_:1}),e[10]||(e[10]=t(" 選題：",-1)),s(i,{href:"https://github.com/lujun9972"},{default:o(()=>[...e[6]||(e[6]=[t("lujun9972",-1)])]),_:1}),e[11]||(e[11]=t(" 譯者：",-1)),s(i,{href:"https://github.com/geekpi"},{default:o(()=>[...e[7]||(e[7]=[t("geekpi",-1)])]),_:1}),e[12]||(e[12]=t(" 校對：",-1)),s(i,{href:"https://github.com/wxy"},{default:o(()=>[...e[8]||(e[8]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[15]||(e[15]=t("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[13]||(e[13]=[t("LCTT",-1)])]),_:1}),e[16]||(e[16]=t(" 原創編譯，",-1)),s(i,{href:"https://linux.cn/"},{default:o(()=>[...e[14]||(e[14]=[t("Linux中國",-1)])]),_:1}),e[17]||(e[17]=t(" 榮譽推出",-1))])])}const C=d(u,[["render",c]]);export{T as __pageData,C as default};
